<script setup>
import {ref,reactive,computed,onMounted,onUnmounted} from 'vue'
import {connectSourcing} from './sourcingRealtime.mjs'
const props=defineProps({api:Function,context:Object,categories:Array})
const rows=ref([]),total=ref(0),page=ref(1),search=ref(''),detail=ref(null),quotes=ref([]),questions=ref([]),notices=ref([]),tasks=ref([]),awards=ref([]),award=ref(null),compare=ref(null),candidates=ref([]),error=ref(''),notice=ref(''),busy=ref(false),editing=ref(false),state=ref(null),own=ref(null),socketStatus=ref('未连接'),bidAmount=ref(''),pending=ref(null),result=ref(null)
const candidateSearch=ref(''),fileLine=ref('')
const form=reactive({}),quote=reactive({lines:[],freight:0,remark:''}),question=reactive({isPublic:true,supplierId:null,question:''}),awardForm=reactive({supplierId:'',reason:'',noHistoryReason:'',discloseLoss:false}),decision=reactive({action:'APPROVE',comment:'',targetId:null,approveNoHistory:false,acknowledgeRisk:false,noHistoryReason:''}),extension=ref(''),reason=ref(''),risk=reactive({supplierId:'',level:'LOW',evidenceRef:'',note:''})
const writer=computed(()=>!props.context.portal&&props.context.roles.some(r=>['SRC-SPE','CAT-MGR','superAdmin'].includes(r))),allowed=computed(()=>!props.context.portal||props.context.roles.some(r=>['ADMIN','QUOTE'].includes(r)))
const states={DRAFT:'草稿',PUBLISHED:'报价中',WITHDRAWN:'已撤回',CLOSED:'已封盘',FAILED:'流标',AWARD_PENDING:'定点审批中',AWARD_APPROVED:'定点待发布',AWARDED:'已定点'}
const p=(path,body,method='GET',raw=false)=>props.api('/sourcing'+path,body,method,raw),post=(path,body={})=>p(path,body,'POST'),stamp=v=>v?new Date(Number(v)).toLocaleString():'—',local=v=>{const d=new Date(Number(v));return new Date(d-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}
let live=null,createKey='',quoteKey='',quoteSignature='',awardKey=''
async function run(fn){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function load(){if(!allowed.value)return;const r=await p('/rfqs?'+new URLSearchParams({current:page.value,size:20,searchKey:search.value}));rows.value=r.records;total.value=r.total;if(props.context.portal)notices.value=await p('/notices');else tasks.value=await p('/tasks')}
function stop(){live?.close();live=null;socketStatus.value='未连接'}
async function inspect(r){stop();editing.value=false;award.value=null;compare.value=null;state.value=null;own.value=null;pending.value=null;result.value=null;detail.value=await p('/rfqs/'+r.id);const d=detail.value;fileLine.value=d.lines[0]?.id||'';questions.value=d.status==='DRAFT'?[]:await p('/rfqs/'+d.id+'/questions');quotes.value=d.strategy==='COMPARE'?await p('/rfqs/'+d.id+'/quotes'):[];quote.lines=d.lines.map(l=>({lineId:l.id,unitPrice:'',leadDays:7}));quote.freight=0;quote.remark='';if(props.context.portal){if(d.status==='AWARDED')result.value=await p('/rfqs/'+d.id+'/result')}else awards.value=await p('/rfqs/'+d.id+'/awards');if(d.strategy==='AUCTION'&&d.status!=='DRAFT'){const initial=await p('/rfqs/'+d.id+'/auction-state');state.value=initial.public;own.value=initial.personal;connect(d.id)}}
function accept(m){if(m.type==='PUBLIC_STATE'||m.publicState){const next=m.publicState||m.state||m;if(!state.value||Number(next.version)>=Number(state.value.version))state.value=next}else if(m.type==='YOUR_STATE'){if(!state.value||Number(m.version)>=Number(state.value.version))own.value=m.state||m}else if(m.type==='ACK'||m.code!==undefined){if(m.code===200){pending.value=null;notice.value='出价已持久保存，请以回执序号为准'}else error.value=m.message||m.msg||'出价未确认，请查询原回执'}}
function connect(rid){const u=new URL('/api/srm-sourcing-ws',location.href);u.protocol=location.protocol==='https:'?'wss:':'ws:';live=connectSourcing({url:u.href,ticket:()=>post('/socket-ticket',{rfqId:rid}),onMessage:accept,onStatus:s=>socketStatus.value=s})}
async function refresh(){if(detail.value)await inspect(detail.value);await load()}
function line(){return {id:'L'+crypto.randomUUID().slice(0,8),material:'',quantity:1,delivery:'',specification:'',benchmark:null,fileIds:[]}}
async function draft(existing=false){stop();editing.value=true;createKey=crypto.randomUUID();if(existing){const d=detail.value;Object.assign(form,{requestKey:createKey,rowVersion:d.rowVersion,rfqNo:d.rfqNo,title:d.title,category:d.category,strategy:d.strategy,currency:d.currency,deadlineText:local(d.deadline),startText:local(d.startAt||Date.now()),supplierIds:d.invites.map(i=>i.supplierId),lines:JSON.parse(JSON.stringify(d.lines)),startingPrice:d.startingPrice,minDecrement:d.minDecrement,antiSnipeMinutes:d.antiSnipeMinutes??5})}else{detail.value=null;Object.assign(form,{requestKey:createKey,rowVersion:0,rfqNo:'',title:'',category:props.categories.find(c=>c.enabled)?.code||'',strategy:'COMPARE',currency:'CNY',deadlineText:local(Date.now()+86400000),startText:local(Date.now()),supplierIds:[],lines:[line()],startingPrice:10000,minDecrement:1,antiSnipeMinutes:5})}await candidateLoad()}
async function candidateLoad(){candidates.value=await p('/candidates?category='+encodeURIComponent(form.category)+'&searchKey='+encodeURIComponent(candidateSearch.value))}
async function save(){const body={...form,deadline:new Date(form.deadlineText).getTime(),startAt:new Date(form.startText).getTime(),lines:form.lines.map(l=>({...l,benchmark:l.benchmark===''?null:l.benchmark}))};delete body.deadlineText;delete body.startText;const d=await post('/rfqs'+(detail.value?'/'+detail.value.id+'/edit':''),body);await inspect(d);await load();notice.value='询价草稿已保存'}
async function command(action){const d=detail.value;await post('/rfqs/'+d.id+'/'+action,{rowVersion:d.rowVersion});await refresh()}
async function extend(){await post('/rfqs/'+detail.value.id+'/extend',{rowVersion:detail.value.rowVersion,deadline:new Date(extension.value).getTime(),reason:reason.value});await refresh()}
async function upload(e){const f=e.target.files[0];if(!f)return;const data=new FormData();data.append('file',f);const target=fileLine.value||detail.value.lines[0].id;const r=await post('/rfqs/'+detail.value.id+'/files',data);await draft(true);(form.lines.find(l=>l.id===target)||form.lines[0]).fileIds.push(r.id||r.fileId);notice.value='规格已上传并绑定所选物料，请保存草稿'}
async function downloadFile(f){const blob=await p('/rfqs/'+detail.value.id+'/files/'+f.id,undefined,'GET',true);download(blob,f.name)}
function download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
async function submitQuote(){const sig=JSON.stringify(quote);if(sig!==quoteSignature){quoteSignature=sig;quoteKey=crypto.randomUUID()}const expectedRound=Math.max(0,...quotes.value.map(q=>Number(q.round)));await post('/rfqs/'+detail.value.id+'/quotes',{requestKey:quoteKey,expectedRound,...quote});quotes.value=await p('/rfqs/'+detail.value.id+'/quotes');quoteSignature='';notice.value='新一轮报价已保存，历史报价保留'}
async function ask(){await post('/rfqs/'+detail.value.id+'/questions',question);question.question='';questions.value=await p('/rfqs/'+detail.value.id+'/questions')}
async function answer(q){await post('/rfqs/'+detail.value.id+'/questions/'+q.id+'/answer',{answer:q.draftAnswer});questions.value=await p('/rfqs/'+detail.value.id+'/questions')}
function bid(){if(pending.value)throw new Error('请先查询上一笔出价回执');pending.value={rfqId:detail.value.id,requestKey:crypto.randomUUID(),expectedVersion:Number(state.value.version),amount:bidAmount.value};live.send('/app/bid/submit',pending.value);notice.value='已发送，正在等待持久化回执'}
async function receipt(){try{const r=await p('/rfqs/'+detail.value.id+'/receipts/'+pending.value.requestKey);notice.value='已确认原出价：'+JSON.stringify(r);pending.value=null}catch(e){error.value=e.message+'；确认未成交后可重发原请求'}}
function retry(){live.send('/app/bid/submit',pending.value)}
async function comparison(){compare.value=await p('/rfqs/'+detail.value.id+'/comparison')}
async function submitAward(){if(!awardKey)awardKey=crypto.randomUUID();award.value=await post('/rfqs/'+detail.value.id+'/awards',{...awardForm,requestKey:awardKey});awardKey='';await load();detail.value=await p('/rfqs/'+detail.value.id)}
async function inspectAward(id){const data=await p('/awards/'+id);if(detail.value?.id!==data.rfqId)await inspect({id:data.rfqId});award.value=data;decision.comment='';decision.targetId=null}
async function decide(task){award.value=await post('/awards/'+award.value.id+'/tasks/'+task.id,decision);await load();if(detail.value)detail.value=await p('/rfqs/'+detail.value.id)}
async function awardAction(action){award.value=await post('/awards/'+award.value.id+'/'+action);await refresh()}
async function saveRisk(){await post('/suppliers/'+risk.supplierId+'/risk',{level:risk.level,evidenceRef:risk.evidenceRef,note:risk.note});notice.value='人工风险依据已保存';if(compare.value)await comparison()}
onMounted(()=>run(load));onUnmounted(stop)
</script>
<template><section class="sourcing-panel" :aria-busy="busy"><p v-if="!allowed" class="info-note">当前联系人无寻源报价权限。</p><template v-else>
<div class="panel-heading"><div><h2>寻源与竞价</h2><p>受邀询报价 · 匿名反向竞价 · 有依据的定点审批</p></div><button class="btn" :disabled="busy" @click="run(refresh)">刷新寻源</button><button :disabled="busy" v-if="writer" class="btn primary" @click="run(()=>draft())">新建询价</button></div>
<p v-if="error" role="alert" class="form-error">{{error}}</p><p v-if="notice" role="status" class="info-note">{{notice}}</p>
<template v-if="!editing"><form class="table-toolbar" @submit.prevent="page=1;run(load)"><input aria-label="寻源搜索" v-model="search" placeholder="询价编号或标题"/><button :disabled="busy" class="btn">查询</button></form><div class="table-scroll"><table><thead><tr><th>询价</th><th>策略</th><th>状态</th><th>截止时间</th><th>操作</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>{{r.title}}<small>{{r.rfqNo}}</small></td><td>{{r.strategy==='AUCTION'?'反向竞价':'询报价'}}</td><td>{{states[r.status]}}</td><td>{{stamp(r.deadline)}}</td><td><button :disabled="busy" class="text-btn" @click="run(()=>inspect(r))">打开询价</button></td></tr></tbody></table></div><p v-if="!rows.length" class="empty-state">当前范围暂无询价。</p><div class="table-footer"><span>共 {{total}} 条</span><button :disabled="page===1" @click="page--;run(load)">上一页</button><span>{{page}}</span><button :disabled="page*20>=total" @click="page++;run(load)">下一页</button></div></template>
<form v-if="editing" class="src-card" @submit.prevent="run(save)"><h3>{{detail?'编辑':'创建'}}询价草稿</h3><div class="src-grid"><label>标题<input v-model="form.title" required maxlength="128"/></label><label>编号（可自动生成）<input v-model="form.rfqNo" maxlength="64"/></label><label>物料品类<select :disabled="busy" v-model="form.category" @change="form.supplierIds=[];run(candidateLoad)"><option v-for="c in categories.filter(c=>c.enabled)" :value="c.code" :key="c.code">{{c.name}}</option></select></label><label>策略<select :disabled="busy" v-model="form.strategy"><option value="COMPARE">询报价</option><option value="AUCTION">反向竞价</option></select></label><label>币种<select :disabled="busy" v-model="form.currency"><option>CNY</option><option>USD</option><option>EUR</option></select></label><label>截止时间<input type="datetime-local" v-model="form.deadlineText" required/></label><label v-if="form.strategy==='AUCTION'">开始时间<input type="datetime-local" v-model="form.startText" required/></label></div>
<template v-if="form.strategy==='AUCTION'"><div class="src-grid"><label>起始总价<input type="number" min="0.01" step="0.01" v-model.number="form.startingPrice" required/></label><label>最小降幅<input type="number" min="0.01" step="0.01" v-model.number="form.minDecrement" required/></label><label>末段顺延分钟（0关闭）<input type="number" min="0" max="60" v-model.number="form.antiSnipeMinutes" required/></label></div><p class="info-note">最后 N 分钟每笔合法出价将截止时间再顺延 N 分钟，连续延时无次数上限。</p></template>
<label>搜索受邀供应商<input aria-label="搜索受邀供应商" v-model="candidateSearch" placeholder="按供应商名称或编号查找"/></label><button :disabled="busy" type="button" class="btn" @click="run(candidateLoad)">查询受邀供应商</button><fieldset><legend>邀请同品类合格供应商（{{form.supplierIds.length}} / 50）</legend><label v-for="s in candidates" :key="s.id" class="src-check"><input type="checkbox" v-model="form.supplierIds" :value="s.id"/>{{s.name}}</label></fieldset>
<div v-for="(l,i) in form.lines" :key="l.id" class="src-card"><h4>物料 {{i+1}}</h4><div class="src-grid"><label>物料名称<input v-model="l.material" required/></label><label>数量<input type="number" min="0.001" step="0.001" v-model.number="l.quantity" required/></label><label>交付要求<input v-model="l.delivery" required/></label><label>基准单价（可选）<input type="number" min="0.0001" step="0.0001" v-model.number="l.benchmark"/></label></div><label>技术规格<textarea v-model="l.specification" maxlength="500"/></label><p v-if="l.fileIds.length">已绑定 {{l.fileIds.length}} 份私有规格</p><button :disabled="busy" v-if="form.lines.length>1" type="button" class="text-btn" @click="form.lines.splice(i,1)">删除此行</button></div><button :disabled="busy" type="button" class="btn" @click="form.lines.push(line())">添加物料</button><button class="btn primary" :disabled="busy">保存草稿</button><button :disabled="busy" type="button" class="btn" @click="editing=false">取消编辑</button></form>
<article v-else-if="detail" class="src-card"><div class="panel-heading"><h3>{{detail.title}} · {{states[detail.status]}}</h3><button :disabled="busy" class="btn" @click="stop();detail=null">关闭详情</button></div><p>{{detail.rfqNo}} · {{detail.currency}} · 截止 {{stamp(detail.deadline)}} · 版本 {{detail.rowVersion}}</p>
<div v-if="writer" class="src-actions"><template v-if="detail.status==='DRAFT'"><button :disabled="busy" class="btn" @click="run(()=>draft(true))">编辑草稿</button><label>规格所属物料<select :disabled="busy" aria-label="规格所属物料" v-model="fileLine"><option v-for="l in detail.lines" :key="l.id" :value="l.id">{{l.material}}</option></select></label><label class="btn">上传规格<input type="file" accept=".pdf,.png,.jpg,.jpeg" @change="e=>run(()=>upload(e))"/></label><button :disabled="busy" class="btn primary" @click="run(()=>command('publish'))">发布邀请</button></template><button :disabled="busy" v-if="['DRAFT','PUBLISHED'].includes(detail.status)" class="btn" @click="run(()=>command('withdraw'))">撤回未报价询价</button></div>
<table><thead><tr><th>物料</th><th>数量</th><th>交付要求</th><th>技术规格</th></tr></thead><tbody><tr v-for="l in detail.lines" :key="l.id"><td>{{l.material}}</td><td>{{l.quantity}}</td><td>{{l.delivery}}</td><td>{{l.specification}}</td></tr></tbody></table><button :disabled="busy" class="text-btn" v-for="f in detail.files" :key="f.id" @click="run(()=>downloadFile(f))">下载 {{f.name}}</button>
<form v-if="writer&&detail.status==='PUBLISHED'" class="table-toolbar" @submit.prevent="run(extend)"><label>延长至<input type="datetime-local" v-model="extension" required/></label><input v-model="reason" placeholder="延期原因" aria-label="延期原因" required/><button :disabled="busy" class="btn">延长截止并通知</button></form>
<template v-if="detail.strategy==='COMPARE'"><h3>报价轮次</h3><p>单价含税，到厂总价＝逐行四舍五入的单价×数量之和＋运费。同一询价使用同一币种。</p><form v-if="context.portal&&detail.status==='PUBLISHED'" @submit.prevent="run(submitQuote)"><div v-for="(l,i) in detail.lines" :key="l.id" class="src-grid"><label>{{l.material}} 单价<input type="number" min="0.0001" step="0.0001" required v-model.number="quote.lines[i].unitPrice"/></label><label>交期（天）<input type="number" min="1" max="3650" required v-model.number="quote.lines[i].leadDays"/></label></div><label>运费<input type="number" min="0" step="0.01" v-model.number="quote.freight" required/></label><label>报价说明<input v-model="quote.remark"/></label><button class="btn primary" :disabled="busy">提交新一轮报价</button></form><div v-for="q in quotes" :key="q.id" class="src-card"><strong>{{context.portal?'本方':q.supplierName}} · 第 {{q.round}} 轮 · 总价 {{q.total}}</strong><p v-for="l in q.payload.lines" :key="l.lineId">{{l.lineId}} · 单价 {{l.unitPrice??'无字段查看权限'}} · 交期 {{l.leadDays}} 天</p><p>运费 {{q.payload.freight}} · {{q.payload.remark}}</p></div></template>
<template v-if="detail.strategy==='AUCTION'&&state"><h3>实时竞价</h3><p role="status">{{socketStatus}} · 序号 {{state.version}} · 截止 {{stamp(state.deadline||state.end)}} · 最低总价 {{state.minimum||state.lowestPrice||'暂无出价'}}</p><p class="info-note">最后 {{detail.antiSnipeMinutes}} 分钟每笔合法出价顺延 {{detail.antiSnipeMinutes}} 分钟；无延时次数上限。最小降幅 {{detail.minDecrement}} {{detail.currency}}。</p><p v-if="!state.cacheReady" class="form-error">竞价校验缓存未就绪，新出价暂停。请联系采购恢复。</p><button :disabled="busy" v-if="writer" class="btn" @click="run(async()=>{await post('/rfqs/'+detail.id+'/recover');await refresh()})">按已保存记录恢复竞价</button><table><thead><tr><th>匿名席位</th><th>总价</th><th>排名</th></tr></thead><tbody><tr v-for="b in state.board||[]" :key="b.alias"><td>{{b.alias}}</td><td>{{b.amount}}</td><td>{{b.rank}}</td></tr></tbody></table><p v-if="own">本方报价 {{own.yourPrice??'暂无'}} · 本方排名 {{own.yourRank??'暂无'}}</p><form v-if="context.portal&&detail.status==='PUBLISHED'" @submit.prevent="run(bid)"><label>新的篮子总价<input type="number" min="0.01" step="0.01" v-model="bidAmount" required/></label><button class="btn primary" :disabled="!!pending||!state.cacheReady||socketStatus!=='已连接'">发送竞价</button></form><div v-if="pending"><p>请求 {{pending.requestKey}} 尚未确认，请勿换新编号重复报价。</p><button :disabled="busy" class="btn" @click="run(receipt)">查询原请求回执</button><button :disabled="busy" class="btn" @click="run(retry)">重发原请求</button><button :disabled="busy" class="btn" @click="pending=null">确认未成交后重填</button></div></template>
<template v-if="detail.status!=='DRAFT'"><h3>公开答疑与私聊</h3><div v-for="q in questions" :key="q.id" class="src-card"><strong>{{q.isPublic?'公开':'本方私聊'}} · {{q.question}}</strong><p>{{q.answer||'待采购答复'}}</p><form v-if="writer&&!q.answer" @submit.prevent="run(()=>answer(q))"><input v-model="q.draftAnswer" aria-label="采购答复" required/><button :disabled="busy" class="btn">发布答复</button></form></div><form v-if="['PUBLISHED','CLOSED'].includes(detail.status)" @submit.prevent="run(ask)"><label class="src-check"><input type="checkbox" v-model="question.isPublic"/>公开给所有受邀供应商</label><select :disabled="busy" v-if="writer&&!question.isPublic" v-model="question.supplierId" required><option :value="null">选择私聊供应商</option><option v-for="i in detail.invites" :key="i.supplierId" :value="i.supplierId">{{i.supplierName}}</option></select><textarea aria-label="寻源问题" v-model="question.question" required maxlength="2000"/><button :disabled="busy" class="btn">提交问题</button></form></template>
<template v-if="!context.portal&&detail.status!=='DRAFT'"><h3>比价与定点依据</h3><button :disabled="busy" class="btn" @click="run(comparison)">查看最新比价</button><button :disabled="busy" class="btn" @click="run(async()=>download(await p('/rfqs/'+detail.id+'/comparison-export',undefined,'GET',true),'比价.xlsx'))">导出比价 Excel</button><template v-if="compare"><p>交付/质量/成本/服务权重 {{compare.weights?.join(' / ')}}；无历史不补默认分，风险未知须明确批准。</p><table><thead><tr><th>排名 / 供应商</th><th>到厂总价</th><th>成本分</th><th>综合分</th><th>交期</th><th>历史与风险</th></tr></thead><tbody><tr v-for="c in compare.candidates" :key="c.supplierId"><td>{{c.rank}} · {{c.supplierName}}</td><td>{{c.total}}</td><td>{{c.costScore}}</td><td>{{c.weightedScore??'无历史，须例外审批'}}</td><td>{{c.leadTimes?.map(l=>l.lineId+': '+l.leadDays+'天').join(' / ')||'见物料要求'}}</td><td>{{c.performance.validMonths}}个月 · {{c.risk.level}}</td></tr></tbody></table></template>
<form v-if="writer&&detail.status==='CLOSED'" @submit.prevent="run(submitAward)"><h4>提交经理定点审批</h4><select :disabled="busy" v-model="awardForm.supplierId" required><option value="">选择受邀候选</option><option v-for="i in detail.invites" :value="i.supplierId" :key="i.supplierId">{{i.supplierName}}</option></select><label>推荐原因<textarea v-model="awardForm.reason" required/></label><label>无历史绩效例外原因<textarea v-model="awardForm.noHistoryReason"/></label><label class="src-check"><input type="checkbox" v-model="awardForm.discloseLoss"/>向落选方披露评审意见</label><button :disabled="busy" class="btn primary">提交定点申请</button></form><h4>定点申请记录</h4><button :disabled="busy" class="text-btn" v-for="a in awards" :key="a.id" @click="run(()=>inspectAward(a.id))">{{a.id}} · {{a.status}}</button></template><div v-if="result" class="info-note">{{result.published?result.message:'定点尚未发布'}}</div>
</article>
<section v-if="!context.portal" class="src-card"><h3>定点审批待办</h3><p v-if="!tasks.length">当前范围无待办。</p><button :disabled="busy" class="text-btn" v-for="t in tasks" :key="t.id" @click="run(()=>inspectAward(t.awardId))">{{t.title}} · {{t.name}}</button></section>
<article v-if="award" class="src-card"><h3>定点申请 · {{award.status}}</h3><p>{{award.reason}}</p><p>无历史例外依据：{{award.noHistoryReason||'无'}}</p><div class="src-grid"><p>推荐供方：<strong>{{award.basis.supplierName}}</strong></p><p>到厂总价：{{award.basis.total}} {{award.basis.currency}}</p><p>成本分：{{award.basis.costScore}} · 综合分：{{award.basis.weightedScore??'无历史，须例外审批'}}</p><p>实际绩效：{{award.basis.performance.validMonths}}个月 · 风险：{{award.basis.risk.level}}</p></div><details><summary>查看依据版本与审计快照</summary><pre>{{JSON.stringify(award.basis,null,2)}}</pre></details><div v-for="a in award.actions" :key="a.createdAt+a.action">{{a.action}} · {{a.comment}}</div><form v-for="t in award.tasks" :key="t.id" @submit.prevent="run(()=>decide(t))"><select :disabled="busy" aria-label="定点审批动作" v-model="decision.action"><option value="APPROVE">批准</option><option value="REJECT">驳回</option><option value="TRANSFER">转办经理</option><option value="REASSIGN">改派候选供应商并重新审批</option></select><select :disabled="busy" v-if="decision.action==='TRANSFER'" aria-label="转办经理" v-model="decision.targetId" required><option :value="null">选择经理</option><option v-for="r in award.reviewers" :key="r.id" :value="r.id">{{r.name}}</option></select><select :disabled="busy" v-if="decision.action==='REASSIGN'" aria-label="改派候选供应商" v-model="decision.targetId" required><option :value="null">选择其他候选供应商</option><option v-for="i in (detail?.invites||[]).filter(i=>i.supplierId!==award.supplierId)" :key="i.supplierId" :value="i.supplierId">{{i.supplierName}}</option></select><label>审批意见<textarea v-model="decision.comment" required/></label><label v-if="decision.action==='REASSIGN'">新候选无历史例外依据<textarea v-model="decision.noHistoryReason"/></label><label class="src-check"><input type="checkbox" v-model="decision.approveNoHistory"/>明确批准无历史绩效例外</label><label class="src-check"><input type="checkbox" v-model="decision.acknowledgeRisk"/>已审阅并确认高风险或未知风险</label><button class="btn primary" :disabled="busy">处理定点审批</button></form><button :disabled="busy" v-if="writer&&award.status==='APPROVED'" class="btn primary" @click="run(()=>awardAction('publish'))">发布定点与落选通知</button><button :disabled="busy" v-if="writer&&['PENDING','APPROVED'].includes(award.status)" class="btn" @click="run(()=>awardAction('withdraw'))">撤回定点申请</button></article>
<form v-if="!context.portal&&context.roles.some(r=>['SQE','CAT-MGR','superAdmin'].includes(r))" class="src-card" @submit.prevent="run(saveRisk)"><h3>人工风险评估</h3><p>登记可追溯依据；未登记时显示 UNKNOWN。外部风险系统尚未接入。</p><div class="src-grid"><label>供应商ID<input v-model="risk.supplierId" required/></label><label>风险等级<select :disabled="busy" v-model="risk.level"><option>LOW</option><option>MEDIUM</option><option>HIGH</option></select></label><label>依据编号<input v-model="risk.evidenceRef" required/></label></div><label>评估说明<textarea v-model="risk.note" required/></label><button :disabled="busy" class="btn">保存风险版本</button></form>
<section v-if="context.portal" class="src-card"><h3>本方通知</h3><p v-for="n in notices" :key="n.id">{{stamp(new Date(n.createdAt).getTime())}} · {{n.message}}</p></section>
</template></section></template>
<style scoped>.src-card{border:1px solid #dbe5df;border-radius:12px;padding:20px;margin:18px 0}.src-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:14px}.src-actions{display:flex;gap:10px;flex-wrap:wrap;margin:14px 0}.sourcing-panel label{display:block;margin:10px 0}.sourcing-panel input:not([type=checkbox]),.sourcing-panel select,.sourcing-panel textarea{display:block;width:100%;padding:9px;border:1px solid #cad6cf;border-radius:6px}.sourcing-panel textarea{min-height:65px}.sourcing-panel .src-check{display:inline-flex;align-items:center;gap:8px;margin-right:18px}.sourcing-panel table{width:100%;border-collapse:collapse}.sourcing-panel td,.sourcing-panel th{padding:10px;text-align:left;border-bottom:1px solid #e5ebe7}.sourcing-panel small{display:block;color:#65776b}.sourcing-panel pre{white-space:pre-wrap;max-height:360px;overflow:auto;font-size:12px}.sourcing-panel .btn{margin:5px}.sourcing-panel fieldset{border:1px solid #dbe5df;border-radius:8px;margin:16px 0}</style>
